/// <summary>
///    AVA <c>createAlerts</c> method.
/// </summary>
void createAlerts()
{
    NDX_KBVLog              kbvLogGrouped;
    NDX_KBVLog              kbvLogCount;
    NDX_KBVLog              kbvLog;
    //NDX_KBVErrorTypes       kbvErrorTypes;
    //NDX_KBVEmployeeError    kbvEmployeeError;

    //ToDo: NDX_EventNotification   alert;
    //ToDo: Not needed: Menufunction            menufunction = new Menufunction(menuitemdisplaystr(NDX_KBVLog), MenuItemType::Display);
    //str                     datasourcename = tablestr(NDX_KBVLog);

    while select kbvLogGrouped
    group by KBVErrors, HeaderRefRecId
    where kbvLogGrouped.HeaderRefRecId == this.RecId
    {
        select firstonly count(RecId) 
        from    kbvLogCount
        group by KBVErrors, HeaderRefRecId
        where   kbvLogCount.HeaderRefRecId == kbvLogGrouped.HeaderRefRecId
            &&  kbvLogCount.KBVErrors == kbvLogGrouped.KBVErrors;

        select firstOnly kbvLog
        where   kbvLog.KBVErrors == kbvLogGrouped.KBVErrors
            &&  kbvLog.HeaderRefRecId == kbvLogGrouped.HeaderRefRecId;

        //ToDo: NDX_EventNotification (missing) -> EventNotificationSync (mmissing) -> EventNotification
