            join    kbvErrorTypes
            where   kbvErrorTypes.KBVError == kbvEmployeeError.NDX_KBVErrors
                &&  kbvErrorTypes.KBVError == kbvLogGrouped.KBVErrors
        {
            alert = NDX_EventNotification::newInfo(strfmt("@NXD10189",  kbvLog.KBVErrors),                                                   //Live Bauvorhaben; Zuständigkeiten: %1
                                                                        "@NXD10188",                                                                             //Live Bauvorhaben; Zuständigkeiten
