                                                                        NoYes::Yes, curext(), kbvLog, datasourcename, menufunction, NoYes::Yes);                 //Zuständigkeiten

            alert.parmUserId(SysCompanyUserInfo::emplId2UserId(kbvEmployeeError.EmplId));
            alert.create();
        }
        */
