}

/// <summary>
///    AVA <c>endLog</c> method.
/// </summary>
/// <param name="warnings">
///    <c>int</c> as type
/// </param>
/// <param name="errors">
///    <c>int</c> as type
/// </param>
void endLog(int warnings, int errors)
{
    ttsbegin;

    this.selectForUpdate(true);
    this.AnzWarnings = warnings;
    this.AnzFehler   = errors;
    this.update();

    ttscommit;
}

/// <summary>
///    AVA <c>startLog</c> method.
/// </summary>
/// <param name="kbvJob">
///    <c>NDX_KBVJob</c> as type
/// </param>
/// <returns>
///    <c>NDX_KBVLogHeader</c> as return value
/// </returns>
static NDX_KBVLogHeader startLog(NDX_KBVJob kbvJob)
{
    NDX_KBVLogHeader    kbvLogHeader;

    kbvLogHeader.KBVJob = kbvJob;
    kbvLogHeader.insert();

    return kbvLogHeader;
}
